    12	public class TourismTaxReportGenerator implements ReportGenerator {
    13	    private static final BigDecimal TAX_PER_GUEST_PER_NIGHT = new BigDecimal("4.50");
    14	
    15	    @Override
    16	    public String generate(List<Reservation> reservations, List<Room> rooms, String monthStr) {
    17	        YearMonth month = YearMonth.parse(monthStr);
    18	
    19	        List<Reservation> monthReservations = reservations.stream()
    20	            .filter(Reservation::isPaid)
    21	            .filter(r -> {
    22	                YearMonth checkInMonth = YearMonth.from(r.getCheckIn());
    23	                return checkInMonth.equals(month);
    24	            })
    25	            .sorted(Comparator.comparing(Reservation::getCheckIn)
    26	                             .thenComparing(Reservation::getId))
    27	            .collect(Collectors.toList());
    28	
    29	        StringBuilder csv = new StringBuilder();
    30	        csv.append("Pousada Maré Alta,tourism-tax,").append(monthStr).append("\n");
    31	        csv.append("reservation,room,check_in,check_out,guests,nights,tax\n");
    32	
    33	        BigDecimal totalTax = BigDecimal.ZERO;
    34	        for (Reservation reservation : monthReservations) {
    35	            BigDecimal tax = TAX_PER_GUEST_PER_NIGHT
    36	                .multiply(BigDecimal.valueOf(reservation.getGuests()))
    37	                .multiply(BigDecimal.valueOf(reservation.getNights()));
    38	
    39	            totalTax = totalTax.add(tax);
    40	
    41	            csv.append(reservation.getId()).append(",")
    42	               .append(reservation.getRoomNumber()).append(",")
    43	               .append(reservation.getCheckIn()).append(",")
    44	               .append(reservation.getCheckOut()).append(",")
    45	               .append(reservation.getGuests()).append(",")
    46	               .append(reservation.getNights()).append(",")
    47	               .append(formatMoney(tax)).append("\n");
    48	        }
    49	
    50	        csv.append("total,").append(formatMoney(totalTax));
    51	
    52	        return csv.toString();
    53	    }
    54	
    55	    private String formatMoney(BigDecimal amount) {
    56	        return amount.toPlainString();
    57	    }
    58	}
