    10	public class ReportService {
    11	    private final ReservationRepository reservationRepository;
    12	    private final RoomRepository roomRepository;
    13	    private final Map<String, ReportGenerator> generators;
    14	
    15	    public ReportService(ReservationRepository reservationRepository, RoomRepository roomRepository) {
    16	        this.reservationRepository = reservationRepository;
    17	        this.roomRepository = roomRepository;
    18	        this.generators = new HashMap<>();
    19	
    20	        generators.put("occupancy", new OccupancyReportGenerator());
    21	        generators.put("revenue", new RevenueReportGenerator());
    22	        generators.put("tourism-tax", new TourismTaxReportGenerator());
    23	        generators.put("rate-plans", new RatePlansReportGenerator());
    24	    }
    25	
    26	    public String generateReport(String reportType, String parameter) {
    27	        ReportGenerator generator = generators.get(reportType);
    28	        if (generator == null) {
    29	            throw new IllegalArgumentException("Unknown report type: " + reportType);
    30	        }
    31	
    32	        return generator.generate(
    33	            reservationRepository.findAll(),
    34	            roomRepository.findAll(),
    35	            parameter
    36	        );
