    16	            .filter(Reservation::isPaid)
    17	            .filter(r -> r.occupiesNight(date))
    18	            .sorted((r1, r2) -> r1.getRoomNumber().compareTo(r2.getRoomNumber()))
    19	            .collect(Collectors.toList());
    20	
    21	        StringBuilder csv = new StringBuilder();
    22	        csv.append("Pousada Maré Alta,occupancy,").append(dateStr).append("\n");
    23	        csv.append("room,type,reservation,check_in,check_out\n");
    24	
    25	        for (Reservation reservation : occupying) {
    26	            Room room = rooms.stream()
    27	                .filter(r -> r.getNumber().equals(reservation.getRoomNumber()))
    28	                .findFirst()
    29	                .orElseThrow();
    30	
    31	            csv.append(reservation.getRoomNumber()).append(",")
    32	               .append(room.getType()).append(",")
    33	               .append(reservation.getId()).append(",")
    34	               .append(reservation.getCheckIn()).append(",")
    35	               .append(reservation.getCheckOut()).append("\n");
