    13	public class RatePlansReportGenerator implements ReportGenerator {
    14	    @Override
    15	    public String generate(List<Reservation> reservations, List<Room> rooms, String monthStr) {
    16	        YearMonth month = YearMonth.parse(monthStr);
    17	
    18	        List<Reservation> monthReservations = reservations.stream()
    19	            .filter(r -> {
    20	                YearMonth checkInMonth = YearMonth.from(r.getCheckIn());
    21	                return checkInMonth.equals(month);
    22	            })
    23	            .filter(r -> r.getNetRevenue().compareTo(BigDecimal.ZERO) > 0)
    24	            .collect(Collectors.toList());
    25	
    26	        Map<RatePlanType, List<Reservation>> byPlan = monthReservations.stream()
    27	            .collect(Collectors.groupingBy(Reservation::getRatePlanType));
    28	
    29	        StringBuilder csv = new StringBuilder();
    30	        csv.append("Pousada Maré Alta,rate-plans,").append(monthStr).append("\n");
    31	        csv.append("rate_plan,reservations,amount\n");
    32	
    33	        BigDecimal grandTotal = BigDecimal.ZERO;
    34	        int totalCount = 0;
    35	
    36	        for (RatePlanType planType : RatePlanType.values()) {
    37	            List<Reservation> planReservations = byPlan.getOrDefault(planType, List.of());
    38	            int count = planReservations.size();
    39	            BigDecimal amount = planReservations.stream()
    40	                .map(Reservation::getNetRevenue)
    41	                .reduce(BigDecimal.ZERO, BigDecimal::add);
    42	
    43	            totalCount += count;
    44	            grandTotal = grandTotal.add(amount);
    45	
    46	            csv.append(planType).append(",")
    47	               .append(count).append(",")
    48	               .append(formatMoney(amount)).append("\n");
    49	        }
    50	
    51	        csv.append("total,").append(totalCount).append(",").append(formatMoney(grandTotal));
    52	
    53	        return csv.toString();
    54	    }
    55	
    56	    private String formatMoney(BigDecimal amount) {
    57	        return amount.toPlainString();
    58	    }
    59	}
