     8	
     9	    public static boolean isHighSeason(LocalDate date) {
    10	        Month month = date.getMonth();
    11	        int day = date.getDayOfMonth();
    12	
    13	        if (month == Month.DECEMBER && day >= HIGH_SEASON_START_DAY) {
    14	            return true;
    15	        }
    16	        if (month == Month.JANUARY || month == Month.FEBRUARY) {
    17	            return true;
    18	        }
    19	        if (month == Month.JULY) {
    20	            return true;
    21	        }
    22	        return false;
    23	    }
    24	}
