    61	            reservation.confirm();
    62	            reservationRepository.save(reservation);
    63	
    64	            Room room = roomRepository.findByNumber(reservation.getRoomNumber()).get();
    65	            String receipt = documentService.generateReceipt(reservation, room);
    66	            String emailBody = documentService.generateConfirmationEmail(reservation, receipt);
