    30	    public boolean hasConflict(String roomNumber, LocalDate checkIn, LocalDate checkOut, Long excludeId) {
    31	        return reservations.values().stream()
    32	            .filter(r -> excludeId == null || r.getId() != excludeId)
    33	            .filter(r -> r.getRoomNumber().equals(roomNumber))
    34	            .filter(Reservation::isActive)
    35	            .anyMatch(r -> periodsOverlap(r.getCheckIn(), r.getCheckOut(), checkIn, checkOut));
