    48	    public BigDecimal getSubtotal() {
    49	        BigDecimal sum = BigDecimal.ZERO;
    50	        LocalDate current = checkIn;
    51	
    52	        while (current.isBefore(checkOut)) {
    53	            BigDecimal nightRate = nightlyRate;
    54	            if (SeasonCalculator.isHighSeason(current)) {
    55	                nightRate = nightRate.multiply(HIGH_SEASON_MULTIPLIER)
    56	                                    .setScale(2, RoundingMode.HALF_EVEN);
    57	            }
    58	            sum = sum.add(nightRate);
    59	            current = current.plusDays(1);
    60	        }
    61	
    62	        return sum.setScale(2, RoundingMode.HALF_EVEN);
