    26	    public Reservation createReservation(String roomNumber, String guestName, String guestEmail,
    27	                                        String guestCpf, LocalDate checkIn, LocalDate checkOut,
    28	                                        int guests, RatePlanType ratePlanType) {
    29	        Room room = roomRepository.findByNumber(roomNumber)
    30	            .orElseThrow(() -> new RoomNotFoundException("Room not found"));
    31	
    32	        if (guests < 1) {
    33	            throw new InvalidRequestException("At least one guest is required");
    34	        }
    35	
    36	        if (guests > room.getCapacity()) {
    37	            throw new CapacityExceededException("Room capacity exceeded");
    38	        }
    39	
    40	        if (checkOut.isBefore(checkIn) || checkOut.equals(checkIn)) {
    41	            throw new InvalidRequestException("Check-out must be after check-in");
    42	        }
    43	
    44	        if (reservationRepository.hasConflict(roomNumber, checkIn, checkOut, null)) {
    45	            throw new RoomUnavailableException("Room not available for selected dates");
    46	        }
    47	
    48	        long id = reservationRepository.getNextId();
    49	        Reservation reservation = new Reservation(id, roomNumber, room.getType(), guestName,
    50	                                                  guestEmail, guestCpf, checkIn, checkOut,
    51	                                                  guests, ratePlanType);
    52	
    53	        return reservationRepository.save(reservation);
