    10	public class DocumentService {
    11	    private static final DateTimeFormatter DATE_FORMATTER = DateTimeFormatter.ofPattern("dd/MM/yyyy");
    12	    private static final NumberFormat CURRENCY_FORMAT = NumberFormat.getCurrencyInstance(new Locale("pt", "BR"));
    13	
    14	    public String generateReceipt(Reservation reservation, Room room) {
    15	        StringBuilder sb = new StringBuilder();
    16	
    17	        sb.append("Comprovante de reserva nº ").append(reservation.getId()).append("\n");
    18	        sb.append("Hóspede: ").append(reservation.getGuestName())
    19	          .append(" (CPF ").append(formatCpf(reservation.getGuestCpf())).append(")\n");
    20	        sb.append("Quarto: ").append(reservation.getRoomNumber())
    21	          .append(" (").append(room.getType()).append(")\n");
    22	        sb.append("Entrada: ").append(reservation.getCheckIn().format(DATE_FORMATTER))
    23	          .append(" | Saída: ").append(reservation.getCheckOut().format(DATE_FORMATTER))
    24	          .append(" | ").append(reservation.getNights()).append(reservation.getNights() == 1 ? " diária" : " diárias").append("\n");
    25	        sb.append("Diárias: ").append(CURRENCY_FORMAT.format(reservation.getSubtotal())).append("\n");
    26	
    27	        if (reservation.getDiscount().compareTo(java.math.BigDecimal.ZERO) > 0) {
    28	            sb.append("Desconto: ").append(CURRENCY_FORMAT.format(reservation.getDiscount())).append("\n");
    29	        }
    30	
    31	        sb.append("Total: ").append(CURRENCY_FORMAT.format(reservation.getTotal()));
    32	
    33	        return sb.toString();
    34	    }
    35	
    36	    public String generateConfirmationEmail(Reservation reservation, String receipt) {
    37	        StringBuilder sb = new StringBuilder();
    38	
    39	        sb.append("Olá, ").append(reservation.getGuestName()).append("!\n\n");
    40	        sb.append("Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n");
    41	        sb.append(receipt).append("\n\n");
    42	        sb.append("A entrada é a partir das 14h, e a saída, até as 12h.\n");
    43	        sb.append("Até breve!");
    44	
    45	        return sb.toString();
    46	    }
    47	
    48	    private String formatCpf(String cpf) {
    49	        if (cpf.length() == 11) {
    50	            return cpf.substring(0, 3) + "." + cpf.substring(3, 6) + "." +
    51	                   cpf.substring(6, 9) + "-" + cpf.substring(9);
    52	        }
    53	        return cpf;
    54	    }
    55	}
